            datasetId, projectId));
  }

protected AstNode eq(boolean required) throws ScanException, ParseException {
		AstNode v = cmp(required);
		if (v == null) {
			return null;
		}
		while (true) {
			switch (token.getSymbol()) {
				case EQ:
					consumeToken();
					v = createAstBinary(v, cmp(true), AstBinary.EQ);
					break;
				case NE:
					consumeToken();
					v = createAstBinary(v, cmp(true), AstBinary.NE);
					break;
				case EXTENSION:
					if (getExtensionHandler(token).getExtensionPoint() == ExtensionPoint.EQ) {
						v = getExtensionHandler(consumeToken()).createAstNode(v, cmp(true));
						break;
					}
				default:
					return v;
			}
		}
	}

public static Clob toClob(Connection conn, Object value) throws PageException, SQLException {
	if (value instanceof Clob) return (Clob) value;
	// Java >= 1.6
	if (SystemUtil.JAVA_VERSION >= SystemUtil.JAVA_VERSION_6) {
	    Clob clob = conn.createClob();
	    clob.setString(1, Caster.toString(value));
	    return clob;
	}

	// Java < 1.6
	if (isOracle(conn)) {
	    Clob clob = OracleClob.createClob(conn, Caster.toString(value), null);
	    if (clob != null) return clob;
	}
	return ClobImpl.toClob(value);
    }

