private ByteBuffer sslDataWrap(ByteBuffer inBBuff, ByteBuffer outBBuff)
                      throws GSSException {
	try {

              if (sslEngine.getHandshakeStatus() !=
			SSLEngineResult.HandshakeStatus.NOT_HANDSHAKING) {
                  throw new Exception("SSLEngine handshaking needed! " +
                        "HandshakeStatus: " +
                        sslEngine.getHandshakeStatus().toString());
              }
		int iter = 0;
	      do {
		logger.debug("PROCESSING DATA (WRAP) " + ++iter +
					 ": " + inBBuff.remaining());
		SSLEngineResult result = sslEngine.wrap(inBBuff, outBBuff);
		if (result.getHandshakeStatus() ==
			SSLEngineResult.HandshakeStatus.NEED_TASK) {
			runDelegatedTasks(sslEngine);
			continue;
		}
		if (result.getStatus() ==
			SSLEngineResult.Status.BUFFER_OVERFLOW) {
		        // just increase it to the size needed.
		        int pktSize = sslEngine.getSession().getPacketBufferSize();
		        ByteBuffer b = ByteBuffer.allocate(pktSize + outBBuff.position());
		        outBBuff.flip();
		        b.put(outBBuff);
		        outBBuff = b;
			continue;
		} else if (result.getStatus() ==
                            SSLEngineResult.Status.BUFFER_UNDERFLOW) {
                	throw new GlobusGSSException(GSSException.FAILURE,
		 		new Exception("Unexpected BUFFER_UNDERFLOW;" +
                        " Handshaking status: " + sslEngine.getHandshakeStatus()));
                }
		if (result.getStatus() !=
			SSLEngineResult.Status.OK) {
               	throw new GlobusGSSException(GSSException.FAILURE,
                                         GlobusGSSException.TOKEN_FAIL,
                                         result.getStatus().toString());
		}
              } while (inBBuff.hasRemaining());

		return outBBuff;
	} catch (Exception e) {
                throw new GlobusGSSException(GSSException.FAILURE, e);
	}
    }

public void resolveBundle (String path, final ResultListener<FileResourceBundle> listener)
    {
        File bfile = getResourceFile(path);
        if (bfile == null) {
            String errmsg = "ResourceManager not configured with resource directory.";
            listener.requestFailed(new IOException(errmsg));
            return;
        }

        final FileResourceBundle bundle = new FileResourceBundle(bfile, true, _unpack);
        if (bundle.isUnpacked()) {
            if (bundle.sourceIsReady()) {
                listener.requestCompleted(bundle);
            } else {
                String errmsg = "Bundle initialization failed.";
                listener.requestFailed(new IOException(errmsg));
            }
            return;
        }

        // start a thread to unpack our bundles
        ArrayList<ResourceBundle> list = Lists.newArrayList();
        list.add(bundle);
        Unpacker unpack = new Unpacker(list, new InitObserver() {
            public void progress (int percent, long remaining) {
                if (percent == 100) {
                    listener.requestCompleted(bundle);
                }
            }
            public void initializationFailed (Exception e) {
                listener.requestFailed(e);
            }
        });
        unpack.start();
    }

