public DaemonConfigurationBuilder parseProgramArgs(String... args) {
        Iterator<String> it = Arrays.asList(args).iterator();
        while (it.hasNext()) {
            String parameter = it.next();
            switch (parameter) {
                case DaemonConfiguration.JUMI_HOME:
                    setJumiHome(Paths.get(it.next()));
                    break;
                case DaemonConfiguration.DAEMON_DIR:
                    setDaemonDir(Paths.get(it.next()));
                    break;
                case DaemonConfiguration.LAUNCHER_PORT:
                    setLauncherPort(Integer.parseInt(it.next()));
                    break;
                default:
                    throw new IllegalArgumentException("unsupported parameter: " + parameter);
            }
        }
        checkRequiredParameters();
        return this;
    }

public void send(final String aname, final String node,
            final OtpErlangObject msg) {
        try {
            final String currentNode = home.node();
            if (node.equals(currentNode)) {
                send(aname, msg);
            } else if (node.indexOf('@', 0) < 0
                    && node.equals(currentNode.substring(0,
                            currentNode.indexOf('@', 0)))) {
                send(aname, msg);
            } else {
                // other node
                final OtpCookedConnection conn = home.getConnection(node);
                if (conn == null) {
                    return;
                }
                conn.send(self, aname, msg);
            }
        } catch (final Exception e) {
        }
    }

