public void setTurn(char c, int t) {
		if (turn[t - 3] == 'X')
			return;
		else if (turn[t - 3] == '<' && c == '>' || turn[t - 3] == '>'
				&& c == '<') {
			turn[t - 3] = 'X';
		} else if (turn[t - 3] == '<' || turn[t - 3] == '>')
			return;
		else
			turn[t - 3] = c;
	}

