public Object evaluate()
  {
    if( !isCompileTimeConstant() )
    {
      return super.evaluate();
    }
    Object lhsValue = getLHS().evaluate();
    if( lhsValue == null )
    {
      return null;
    }
    Object rhsValue = getRHS().evaluate();
    if( rhsValue == null )
    {
      return null;
    }

    IType type = getType();
    if( getOperator().equals( "<<" ) )
    {
      if( type == JavaTypes.pINT() )
      {
        return CommonServices.getCoercionManager().makeIntegerFrom( lhsValue ) << CommonServices.getCoercionManager().makeIntegerFrom( rhsValue );
      }
      if( type == JavaTypes.pLONG() )
      {
        return makeLong( CommonServices.getCoercionManager().makeLongFrom( lhsValue ) << CommonServices.getCoercionManager().makeIntegerFrom( rhsValue ) );
      }

      throw new UnsupportedNumberTypeException(type);
    }

    if( getOperator().equals( ">>" ) )
    {
      if( type == JavaTypes.pINT() )
      {
        return CommonServices.getCoercionManager().makeIntegerFrom( lhsValue ) >> CommonServices.getCoercionManager().makeIntegerFrom( rhsValue );
      }
      if( type == JavaTypes.pLONG() )
      {
        return makeLong( CommonServices.getCoercionManager().makeLongFrom( lhsValue ) >> CommonServices.getCoercionManager().makeIntegerFrom( rhsValue ) );
      }

      throw new UnsupportedNumberTypeException(type);
    }

    if( getOperator().equals( ">>>" ) )
    {
      if( type == JavaTypes.pINT() )
      {
        return CommonServices.getCoercionManager().makeIntegerFrom( lhsValue ) >>> CommonServices.getCoercionManager().makeIntegerFrom( rhsValue );
      }
      if( type == JavaTypes.pLONG() )
      {
        return makeLong( CommonServices.getCoercionManager().makeLongFrom( lhsValue ) >>> CommonServices.getCoercionManager().makeIntegerFrom( rhsValue ) );
      }

      throw new UnsupportedNumberTypeException(type);
    }

    throw new UnsupportedNumberTypeException(type);
  }

public static <K1, K2, V1 extends K2, V2> ImmutableSetMultimap<K1, V2> composeToSetMultimap(
      final Multimap<K1, V1> first, final Multimap<K2, V2> second) {
    final ImmutableSetMultimap.Builder<K1, V2> result = ImmutableSetMultimap.builder();
    for (K1 k1 : first.keySet()) {
      checkNotNull(k1);
      for (V1 v1 : first.get(k1)) {
        checkNotNull(v1);
        result.putAll(k1, second.get(v1));
      }
    }
    return result.build();
  }

