public static double reduce(
        DoubleTuple t0, double identity, DoubleBinaryOperator op)
    {
        double result = identity;
        int n = t0.getSize();
        for (int i=0; i<n; i++)
        {
            double operand0 = t0.get(i);
            result = op.applyAsDouble(result, operand0);
        }
        return result;
    }

