void processAlterTableAddUniqueConstraint(Table table, HsqlName name, boolean assumeUnique) {
        boolean isAutogeneratedName = false;
        if (name == null) {
            name = database.nameManager.newAutoName("CT",
                    table.getSchemaName(), table.getName(),
                    SchemaObject.CONSTRAINT);
            isAutogeneratedName = true;

        }

        // A VoltDB extension to "readColumnList(table, false)" to support indexed expressions.
        java.util.List<Expression> indexExprs = XreadExpressions(null);
        OrderedHashSet set = getSimpleColumnNames(indexExprs);
        int[] cols = getColumnList(set, table);
        /* disable 1 line ...
        int[] cols = this.readColumnList(table, false);
        ... disabled 1 line */
        // End of VoltDB extension

        session.commit(false);

        TableWorks tableWorks = new TableWorks(session, table);

        // A VoltDB extension to support indexed expressions and the assume unique attribute
        if ((indexExprs != null) && (cols == null)) {
            // A VoltDB extension to support indexed expressions.
            // Not just indexing columns.
            // The meaning of cols shifts here to be
            // the set of unique base columns for the indexed expressions.
            set = getBaseColumnNames(indexExprs);
            cols = getColumnList(set, table);
            tableWorks.addUniqueExprConstraint(cols, indexExprs.toArray(new Expression[indexExprs.size()]), name, isAutogeneratedName, assumeUnique);
            return;
        }
        tableWorks.addUniqueConstraint(cols, name, isAutogeneratedName, assumeUnique);
        /* disable 1 line ...
        tableWorks.addUniqueConstraint(cols, name);
        ... disabled 1 line */
        // End of VoltDB extension
    }

@Override
  public FastSet difference(IntSet other)
  {
    if (other == null || other.isEmpty()) {
      return clone();
    }
    if (other == this || isEmpty()) {
      return empty();
    }

    final FastSet o = convert(other);
    FastSet res = new FastSet(firstEmptyWord);
    res.firstEmptyWord = firstEmptyWord;

    final int[] localWords = words;     // faster
    final int[] localOtherWords = o.words;   // faster
    final int[] localResWords = res.words;   // faster

    int i = 0;
    final int m = Math.min(firstEmptyWord, o.firstEmptyWord);
    for (; i < m; i++) {
      localResWords[i] = localWords[i] & ~localOtherWords[i];
    }
    if (i < firstEmptyWord) {
      System.arraycopy(localWords, i, localResWords, i, firstEmptyWord - i);
    } else {
      res.fixFirstEmptyWord();
    }
    res.size = -1;
    return res;
  }

@Override
    public void coreUpdateCatalog(final long timestamp, final boolean isStreamUpdate, final String catalogDiffs) throws EEException {
        int result = ExecutionEngine.ERRORCODE_ERROR;

        try {
            final byte catalogBytes[] = catalogDiffs.getBytes("UTF-8");
            verifyDataCapacity(catalogBytes.length + 100);
            m_data.clear();
            m_data.putInt(Commands.UpdateCatalog.m_id);
            m_data.putLong(timestamp);
            m_data.putInt(isStreamUpdate ? 1 : 0);
            m_data.put(catalogBytes);
            m_data.put((byte)'\0');
        } catch (final UnsupportedEncodingException ex) {
            Logger.getLogger(ExecutionEngineIPC.class.getName()).log(
                    Level.SEVERE, null, ex);
        }

        try {
            m_data.flip();
            m_connection.write();
            result = m_connection.readStatusByte();
        } catch (final IOException e) {
            System.out.println("Exception: " + e.getMessage());
            throw new RuntimeException(e);
        }
        checkErrorCode(result);
    }

public static final <T> Field getField(Class<T> cls, String fieldName) {
        try {
            Field f = cls.getDeclaredField(fieldName);
            f.setAccessible(true);
            return f;
        } catch (SecurityException e) {
            throw new RuntimeException(e);
        } catch (NoSuchFieldException e) {
            if (cls.getSuperclass() != null) {
                return getField(cls.getSuperclass(), fieldName);
            }
            throw new RuntimeException(e);
        }
    }

