private void issueStreamError(ChannelHandlerContext ctx, int streamId, SpdyStreamStatus status) {
        boolean fireChannelRead = !spdySession.isRemoteSideClosed(streamId);
        ChannelPromise promise = ctx.newPromise();
        removeStream(streamId, promise);

        SpdyRstStreamFrame spdyRstStreamFrame = new DefaultSpdyRstStreamFrame(streamId, status);
        ctx.writeAndFlush(spdyRstStreamFrame, promise);
        if (fireChannelRead) {
            ctx.fireChannelRead(spdyRstStreamFrame);
        }
    }

public static void parseParameters( final Map<String, String[]> map, final byte[] data, final String encoding )
        throws UnsupportedEncodingException
    {

        if ( data != null && data.length > 0 )
        {
            int ix = 0;
            int ox = 0;
            String key = null;
            String value = null;
            while ( ix < data.length )
            {
                final byte c = data[ix++];
                switch ( (char) c )
                {
                    case '&':
                        value = new String( data, 0, ox, encoding );
                        if ( key != null )
                        {
                            putMapEntry( map, key, value );
                            key = null;
                        }
                        ox = 0;
                        break;
                    case '=':
                        if ( key == null )
                        {
                            key = new String( data, 0, ox, encoding );
                            ox = 0;
                        }
                        else
                        {
                            data[ox++] = c;
                        }
                        break;
                    case '+':
                        data[ox++] = (byte) ' ';
                        break;
                    case '%':
                        data[ox++] = (byte) ( ( convertHexDigit( data[ix++] ) << 4 ) + convertHexDigit( data[ix++] ) );
                        break;
                    default:
                        data[ox++] = c;
                }
            }
            // The last value does not end in '&'. So save it now.
            if ( key != null )
            {
                value = new String( data, 0, ox, encoding );
                putMapEntry( map, key, value );
            }
        }

    }

public <T> Response<T> postJson(Endpoint endpoint, Object requestMessage, Class<T> responseClass, NameValuePair... headers) throws IOException {
        if (requestMessage == null) {
            return post(endpoint, responseClass, headers);
        } // deal with null case

        // Create the request
        HttpPost post = new HttpPost(endpoint.url());
        post.setHeaders(combineHeaders(headers));

        // Add the request message if there is one
        post.setEntity(serialiseRequestMessage(requestMessage));

        // Send the request and process the response
        try (CloseableHttpResponse response = httpClient().execute(post)) {
            T body = deserialiseResponseMessage(response, responseClass);
            return new Response<>(response.getStatusLine(), body);
        }
    }

