private ConversationMetadata resolveMetadata() throws ConversationMetadataLoadException {
		checkConversationQueue();

		try {
			// attempt to load the encrypted metadata file
			File metaFile = new File(conversationsStorageDir, CONVERSATION_METADATA_FILE);
			if (metaFile.exists()) {
				ApptentiveLog.v(CONVERSATION, "Loading metadata file: %s", metaFile);
				return ObjectSerialization.deserialize(metaFile, ConversationMetadata.class, encryptionKey);
			}

			// attempt to load the legacy metadata file
			metaFile = new File(conversationsStorageDir, CONVERSATION_METADATA_FILE_LEGACY_V1);
			if (metaFile.exists()) {
				ApptentiveLog.v(CONVERSATION, "Loading legacy v1 metadata file: %s", metaFile);
				try {
					return ObjectSerialization.deserialize(metaFile, ConversationMetadata.class);
				} finally {
					// we need to delete the legacy file to avoid the data being loaded next time
					boolean fileDeleted = metaFile.delete();
					ApptentiveLog.v(CONVERSATION, "Legacy metadata file deleted: %b", fileDeleted);
				}
			}

			ApptentiveLog.v(CONVERSATION, "No metadata files");
		} catch (Exception e) {
			ApptentiveLog.e(CONVERSATION, e, "Exception while loading conversation metadata");
			logException(e);
			// if we fail to load the metadata - we would not create a new one - just throw an exception
			throw new ConversationMetadataLoadException("Unable to load metadata", e);
		}

		return new ConversationMetadata();
	}

public CommPort open(String TheOwner, int i) throws gnu.io.PortInUseException {

        LOGGER.fine("CommPortIdentifier:open(" + TheOwner + ", " + i + ")");

        boolean isAvailable;
        synchronized (this) {
            isAvailable = this.Available;
            if (isAvailable) {
                //assume ownership inside the synchronized block
                this.Available = false;
                this.Owner = TheOwner;
            }
        }
        if (!isAvailable) {
            long waitTimeEnd = System.currentTimeMillis() + i;
            //fire the ownership event outside the synchronized block
            fireOwnershipEvent(CommPortOwnershipListener.PORT_OWNERSHIP_REQUESTED);
            long waitTimeCurr;
            synchronized (this) {
                while (!Available && (waitTimeCurr = System.currentTimeMillis()) < waitTimeEnd) {
                    try {
                        wait(waitTimeEnd - waitTimeCurr);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
                isAvailable = this.Available;
                if (isAvailable) {
                    //assume ownership inside the synchronized block
                    this.Available = false;
                    this.Owner = TheOwner;
                }
            }
        }
        if (!isAvailable) {
            throw new gnu.io.PortInUseException(getCurrentOwner());
        }
        //At this point, the CommPortIdentifier is owned by us.
        try {
            if (commPort == null) {
                commPort = RXTXDriver.getCommPort(portName, portType);
            }
            if (commPort != null) {
                fireOwnershipEvent(CommPortOwnershipListener.PORT_OWNED);
                return commPort;
            } else {
                String err_msg;
                try {
                    err_msg = native_psmisc_report_owner(portName);
                } catch (Throwable t) {
                    err_msg = "Port " + portName + " already owned... unable to open.";
                }
                throw new gnu.io.PortInUseException(err_msg);
            }
        } finally {
            if (commPort == null) {
                //something went wrong reserving the commport -> unown the port
                synchronized (this) {
                    this.Available = true;
                    this.Owner = null;
                }
            }
        }
    }

