ContentMatcher remove(
    Conjunction selector,
    MatchTarget object,
    InternTable subExpr,
    OrdinalPosition parentId)
    throws MatchingException
  {
    SimpleTest test = Factory.findTest(ordinalPosition, selector);
    if (test == null)
      super.remove(selector, object, subExpr, ordinalPosition);
    else
      if (test.getKind() == SimpleTest.NULL)
        nullChild =
          (ContentMatcher) nullChild.remove(selector, object, subExpr, ordinalPosition);
      else
        if (test.getKind() == SimpleTest.NOTNULL)
          notNullChild =
            (ContentMatcher) notNullChild.remove(
              selector,
              object,
              subExpr,
              ordinalPosition);
        else
          handleRemove(test, selector, object, subExpr, ordinalPosition);
    if (isEmpty())
    {
      if (vacantChild instanceof DifficultMatcher) 
      {
        // reset the vacant child's ordinal position to our parent's, as this SimpleMatcher is
        // to be deleted
        vacantChild.ordinalPosition = parentId;
      }
      return vacantChild;
    }
    else
      return this;
  }

public static Object deepCopy(Object src) throws InstantiationException, IllegalAccessException
	{
		Class<?> clazz = src.getClass();

		// Just check if the object is mutable.
		// We assume the object that is final is likely immutable. 
		// It's true for String, Integer and other data types.
		if(Modifier.isFinal(clazz.getModifiers()))
		{
          return src; 
		}

		Object dst = clazz.newInstance();
		if(src instanceof Calendar)
		{
			((Calendar)dst).setTimeInMillis(((Calendar)src).getTimeInMillis());
			return dst;
		}

		Field[] fields = clazz.getFields();
		for(int i=0; i<fields.length; i++)
		{
			Object fObj = fields[i].get(src);
			if(fObj == null)
			{
				continue;
			}
			Class<?> fRealType = fObj.getClass();
			if((!fRealType.isPrimitive()) 
			  || (!fRealType.isEnum())
			  || fRealType.getPackage() != JAVA_LANG_PKG)
			{
				if(fRealType.isArray())
				{
					Object[] items = (Object[]) fObj;
					fObj = Array.newInstance(fRealType.getComponentType(), items.length);
					for(int j=0; j<items.length; j++)
					{
						Array.set(fObj, j, deepCopy(items[j]));
					}
				}
				else
				{
					fObj = deepCopy(fObj);
				}
			}
			fields[i].set(dst, fObj);
		}

		return dst;
	}

