public static boolean memcmp( byte[] a, int a_offset, byte[] b, int b_offset, int length ) {
        if ((a == null) && (b == null)) {
            return true;
        }

        if ((a == null) || (b == null)) {
            return false;
        }

        for( int i = 0; i < length; ++i, ++a_offset, ++b_offset )
            if (a[a_offset] != b[b_offset]) {
                return false;
            }

        return true;
    }

