AmqpBuffer putMethodArguments(Object[] args, List<Parameter> formalParams)
    {

        for (int i = 0; i < formalParams.size(); i++)
        {

            String type = formalParams.get(i).type;

            if (type == null)
            {
                throw new IllegalStateException("Unknown AMQP domain " + type);
            }
            String typeMap = getMappedType(type);

            putObjectOfType(typeMap, args[i]);
            // support packing of consecutive bits into a single byte
            this.bitCount = (byte)((typeMap == "Bit") ? this.bitCount + 1 : 0);
        }
        return this;
    }

protected void emitRecord(T record, KafkaTopicPartitionState<KPH> partitionState, long offset) throws Exception {

		if (record != null) {
			if (timestampWatermarkMode == NO_TIMESTAMPS_WATERMARKS) {
				// fast path logic, in case there are no watermarks

				// emit the record, using the checkpoint lock to guarantee
				// atomicity of record emission and offset state update
				synchronized (checkpointLock) {
					sourceContext.collect(record);
					partitionState.setOffset(offset);
				}
			} else if (timestampWatermarkMode == PERIODIC_WATERMARKS) {
				emitRecordWithTimestampAndPeriodicWatermark(record, partitionState, offset, Long.MIN_VALUE);
			} else {
				emitRecordWithTimestampAndPunctuatedWatermark(record, partitionState, offset, Long.MIN_VALUE);
			}
		} else {
			// if the record is null, simply just update the offset state for partition
			synchronized (checkpointLock) {
				partitionState.setOffset(offset);
			}
		}
	}

