		v |= ((getByte() & 0xFFL) << 40);
		v |= ((getByte() & 0xFFL) << 32);
		v |= ((getByte() & 0xFFL) << 24);
		v |= ((getByte() & 0xFFL) << 16);
		v |= ((getByte() & 0xFFL) << 8);
		v |= (getByte() & 0xFFL);
		return v;
	}

