public static ChannelBuffer writeStrings(Charset charset, String... msgs)
	{
		ChannelBuffer buffer = null;
		for (String msg : msgs)
		{
			if (null == buffer)
			{
				buffer = writeString(msg, charset);
			}
			else
			{
				ChannelBuffer theBuffer = writeString(msg,charset);
				if(null != theBuffer)
				{
