protected Object findValue(String expr, String field, String errorMsg) {
    if (expr == null) {
      throw fieldError(field, errorMsg, null);
    } else {
      Object value = null;
      Exception problem = null;
      try {
        value = findValue(expr);
      } catch (Exception e) {
        problem = e;
      }

      if (value == null) { throw fieldError(field, errorMsg, problem); }

      return value;
    }
  }

