original_code:
public TaskMetricGroup addTaskForJob(
			final JobID jobId,
			final String jobName,
			final JobVertexID jobVertexId,
			final ExecutionAttemptID executionAttemptId,
			final String taskName,
			final int subtaskIndex,
			final int attemptNumber) {
		Preconditions.checkNotNull(jobId);

		String resolvedJobName = jobName == null || jobName.isEmpty()
			? jobId.toString()
			: jobName;

		// we cannot strictly lock both our map modification and the job group modification
		// because it might lead to a deadlock
		while (true) {
			// get or create a jobs metric group
			TaskManagerJobMetricGroup currentJobGroup;
			synchronized (this) {
				currentJobGroup = jobs.get(jobId);

				if (currentJobGroup == null || currentJobGroup.isClosed()) {
					currentJobGroup = new TaskManagerJobMetricGroup(registry, this, jobId, resolvedJobName);
					jobs.put(jobId, currentJobGroup);
				}
			}

			// try to add another task. this may fail if we found a pre-existing job metrics
			// group and it is closed concurrently
			TaskMetricGroup taskGroup = currentJobGroup.addTask(
				jobVertexId,
				executionAttemptId,
				taskName,
				subtaskIndex,
				attemptNumber);

			if (taskGroup != null) {
				// successfully added the next task
				return taskGroup;
			}

			// else fall through the loop
		}
	}

private boolean authenticate(HttpPostCommand command, final String groupName, final String pass)
            throws UnsupportedEncodingException {
        String decodedName = URLDecoder.decode(groupName, "UTF-8");
        SecurityContext securityContext = textCommandService.getNode().getNodeExtension().getSecurityContext();
        if (securityContext == null) {
            final GroupConfig groupConfig = textCommandService.getNode().getConfig().getGroupConfig();
            if (pass != null && !pass.isEmpty()) {
                logger.fine("Password was provided but the Hazelcast Security is disabled.");
            }
            return groupConfig.getName().equals(decodedName);
        }
        if (pass == null) {
            logger.fine("Empty password is not allowed when the Hazelcast Security is enabled.");
            return false;
        }
        String decodedPass = URLDecoder.decode(pass, "UTF-8");
        UsernamePasswordCredentials credentials = new UsernamePasswordCredentials(groupName, decodedPass);
        try {
            LoginContext lc = securityContext.createMemberLoginContext(credentials);
            lc.login();
        } catch (LoginException e) {
            return false;
        }
        return true;
    }

public void runCleanupOperation() {
        final SQLiteDatabase db = getDb();
        if (db == null || !db.isOpen()) {
            if (Configuration.getInstance().isDebugMode()) {
                Log.d(IMapView.LOGTAG, "Finished init thread, aborted due to null database reference");
            }
            return;
        }

        // index creation is run now (regardless of the table size)
        // therefore potentially on a small table, for better index creation performances
        createIndex(db);

        final long dbLength = db_file.length();
        if (dbLength <= Configuration.getInstance().getTileFileSystemCacheMaxBytes()) {
            return;
        }

        runCleanupOperation(
                dbLength - Configuration.getInstance().getTileFileSystemCacheTrimBytes(),
                Configuration.getInstance().getTileGCBulkSize(),
                Configuration.getInstance().getTileGCBulkPauseInMillis(),
                true);
    }

