  )
  {
    Request request;
    try {
      request = indexingServiceClient.makeRequest(
          HttpMethod.GET,
          StringUtils.format("/druid/indexer/v1/tasks"),
          false
      );
    }
    catch (IOException e) {
      throw new RuntimeException(e);
