public int size() {
        restartFromHead: for (;;) {
            int count = 0;
            for (Node<E> p = first(); p != null;) {
                if (p.item != null)
                    if (++count == Integer.MAX_VALUE)
                        break;  // @see Collection.size()
                if (p == (p = p.next))
                    continue restartFromHead;
            }
            return count;
        }
    }

public static void runExample(
      AdManagerServices adManagerServices, AdManagerSession session, long orderId)
      throws RemoteException {
    // Get the OrderService.
    OrderServiceInterface orderService =
        adManagerServices.get(session, OrderServiceInterface.class);

    // Create a statement to only select a single order by ID.
    StatementBuilder statementBuilder =
        new StatementBuilder()
            .where("id = :id")
            .orderBy("id ASC")
            .limit(1)
            .withBindVariableValue("id", orderId);

    // Get the order.
    OrderPage page = orderService.getOrdersByStatement(statementBuilder.toStatement());

    Order order = Iterables.getOnlyElement(Arrays.asList(page.getResults()));

    // Update the order's notes.
    order.setNotes("Spoke to advertiser. All is well.");

    // Update the order on the server.
    Order[] orders = orderService.updateOrders(new Order[] {order});

    for (Order updatedOrder : orders) {
      System.out.printf(
          "Order with ID %d and name '%s' was updated.%n",
          updatedOrder.getId(), updatedOrder.getName());
    }
  }

