public String toQueryString(Criteria criteria, CriteriaQueryBuilder queryBuilder) {

    // fallback for empty criteria list
    if( criterionList.isEmpty() ) {
      return "1=1";
    }

    // build junction
    StringBuilder builder = new StringBuilder();
    builder.append("(");

    Iterator<Criterion> critIter = criterionList.iterator();
    while( critIter.hasNext() ) {

      // add JPQL string
      builder.append( critIter.next().toQueryString(criteria, queryBuilder) );

      // add op if more entries follow
      if( critIter.hasNext() ) {
        builder.append(' ').append(op).append(' ');
      }

    }

    builder.append(")");
    return builder.toString();

  }

@CheckForNull
    public <T> Optional<T> lookup(@Nonnull Resource resource, @Nonnull Key key) {
        if (resource == null) {
            throw new IllegalArgumentException("Method argument resource must not be null");
        }
        if (key == null) {
            throw new IllegalArgumentException("Method argument key must not be null");
        }

        if (this.caches.isEmpty()) {
            return null;
        }

        final Key lookupKey = key(resource, key);
        for (ResourceModelCache cache : this.caches) {
            final Optional<T> model = cache.get(lookupKey);
            if (model == empty()) {
                return model;
            }

            if (model != null) {
                metaDataRegistrar.get(model.get().getClass()).getStatistics().countCacheHit();
                return model;
            }
        }

        // Null signals that the model was never stored in the cache, i.e. we do not know whether
        // the model can be resolved to anything.
        return null;
    }

