@Override
  public int getFileCrc(Path f) throws IOException {
    File p2f = pathToFile(f);
    DataChecksum checksum = DataChecksum.newDataChecksum(DataChecksum.CHECKSUM_CRC32, 1);
    byte[] buf = new byte[1024];
    DataInputStream streamIn = new DataInputStream(new BufferedInputStream(
        new FileInputStream(p2f), 128 * 1024));
    try {
      while (true) {
        int bytesRead = streamIn.read(buf);
        if (bytesRead == -1) {
          break;
        } else
          checksum.update(buf, 0, bytesRead);
      }
      return (int) checksum.getValue();
    } finally {
      IOUtils.closeStream(streamIn);
    }
  }

public static boolean isJavaVersionOK() {
        boolean isJavaVersionOK = true;
        String versionStr = System.getProperty("java.version");
        String[] parts;
        double version;
        if (versionStr.contains(".")) {
          parts = versionStr.split("\\.");
	}
	else {
          parts = new String[]{versionStr};
	}
	if (parts.length == 1) {
          try {
            version = Double.parseDouble(parts[0]);
	  }
	  catch (Exception e) {
            System.err.println("Unparsable Java version: " + versionStr);
            return false;
	  }
	}
	else {
          try {
            version = Double.parseDouble(parts[0]) + Double.parseDouble(parts[1]) / 10;
	  }
	  catch (Exception e) {
            System.err.println("Unparsable Java version: " + versionStr);
            return false;
	  }
	}
        if (version < 1.8) {
            isJavaVersionOK = false;
            System.err.println();
            System.err.println(Globals.getWorkbenchInfoString());
            System.err.println();
            System.err.print("Java 8 or higher is required to run MOA. ");
            System.err.println("Java version " + versionStr + " found");
        }
        return isJavaVersionOK;
    }

