@Override
  public final String makeFilter(final Class<?> pEntityClass,
    final Map<String, Object> pAddParam) throws Exception {
    if (!APersistableBase.class.isAssignableFrom(pEntityClass)) {
      throw new ExceptionWithCode(ExceptionWithCode.CONFIGURATION_MISTAKE,
        "This class not descendant of APersistableBase: "
          + pEntityClass);
    }
    int requestedDatabaseId;
    try {
      requestedDatabaseId = Integer.parseInt(pAddParam
        .get("requestedDatabaseId").toString());
    } catch (Exception e) {
      throw new ExceptionWithCode(ExceptionWithCode.WRONG_PARAMETER,
        "Wrong or missing parameter requestedDatabaseId (in pAddParam): "
          + pAddParam.get("requestedDatabaseId"));
    }
    String queryMaxIdBirth = "select max(IDBIRTH) as MAX_IDBIRTH from "
    + pEntityClass.getSimpleName().toUpperCase() + " where IDDATABASEBIRTH="
      + requestedDatabaseId + ";";
    Long maxIdBirth = this.srvDatabase
      .evalLongResult(queryMaxIdBirth, "MAX_IDBIRTH");
    if (maxIdBirth == null) {
      maxIdBirth = 0L;
    }
    String tblNm = pEntityClass.getSimpleName().toUpperCase();
    return "(" + tblNm + ".ITSID>" + maxIdBirth + " and " + tblNm
      + ".IDDATABASEBIRTH=" + requestedDatabaseId + ")";
  }

private Collection<JcrProperty> getProperties( String repository, String workspace, String path, Node node ) throws RepositoryException {
        ArrayList<PropertyDefinition> names = new ArrayList<>();

        NodeType primaryType = node.getPrimaryNodeType();
        PropertyDefinition[] defs = primaryType.getPropertyDefinitions();

        names.addAll(Arrays.asList(defs));

        NodeType[] mixinType = node.getMixinNodeTypes();
        for (NodeType type : mixinType) {
            defs = type.getPropertyDefinitions();
            names.addAll(Arrays.asList(defs));
        }

        ArrayList<JcrProperty> list = new ArrayList<>();
        for (PropertyDefinition def :  names) {

            String name = def.getName();
            String type = PropertyType.nameFromValue(def.getRequiredType());

            Property p = null;
            try {
                p = node.getProperty(def.getName());
            } catch (PathNotFoundException e) {
            }

            String display = values(def, p);
            String value = def.isMultiple() ? multiValue(p)
                    : singleValue(p, def, repository, workspace, path);
            list.add(new JcrProperty(name, type, value, display));

        }
        return list;
    }

