public boolean updateSourceStream(SIMPMessage msg, boolean isSilence) throws SIResourceException
  {
    if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled())
      SibTr.entry(tc, "updateSourceStream", new Object[] { msg });

    boolean sendMessage = false;

    SIBUuid12 streamID = msg.getGuaranteedStreamUuid();

    StreamSet streamSet = getStreamSet();

    if(!streamID.equals(streamSet.getStreamID()))
    {
      SIResourceException e = new SIResourceException(nls.getFormattedMessage(
        "INTERNAL_MESSAGING_ERROR_CWSIP0001",
        new Object[] {
          "com.ibm.ws.sib.processor.gd.SourceStreamManager",
          "1:1244:1.102" },
        null));

      // FFDC
      FFDCFilter.processException(
        e,
        "com.ibm.ws.sib.processor.gd.SourceStreamManager.updateSourceStream",
        "1:1251:1.102",
        this);

      SibTr.exception(tc, e);
      SibTr.error(tc, "INTERNAL_MESSAGING_ERROR_CWSIP0001",
        new Object[] {
          "com.ibm.ws.sib.processor.gd.SourceStreamManager",
          "1:1258:1.102" });

      if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled())
        SibTr.exit(tc, "updateSourceStream", e);

      throw e;
    }

    int priority = msg.getPriority();
    Reliability reliability = msg.getReliability();

    // Get the stream. Note that no synchronization is required here
    // since we can't be here if a flush is in progress.
    SourceStream sourceStream = (SourceStream) streamSet.getStream(priority,reliability);

    if(sourceStream != null)
    {
      // Write the value message to the stream
      // This will also write a range of Completed ticks between
      // the previous Value tick and the new one
      if(isSilence)
        sendMessage = sourceStream.writeSilence(msg);
      else
        sendMessage = sourceStream.writeValue(msg);
    }
    else
    {
      // The message must be EXPRESS so we always want to send it
      sendMessage = true;
    }

    if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled())
      SibTr.exit(tc, "updateSourceStream", Boolean.valueOf(sendMessage));

    return sendMessage;
  }

private static Set<ClassInfo> filterClassInfo(final Collection<ClassInfo> classes, final ScanSpec scanSpec,
            final boolean strictWhitelist, final ClassType... classTypes) {
        if (classes == null) {
            return Collections.<ClassInfo> emptySet();
        }
        boolean includeAllTypes = classTypes.length == 0;
        boolean includeStandardClasses = false;
        boolean includeImplementedInterfaces = false;
        boolean includeAnnotations = false;
        for (final ClassType classType : classTypes) {
            switch (classType) {
            case ALL:
                includeAllTypes = true;
                break;
            case STANDARD_CLASS:
                includeStandardClasses = true;
                break;
            case IMPLEMENTED_INTERFACE:
                includeImplementedInterfaces = true;
                break;
            case ANNOTATION:
                includeAnnotations = true;
                break;
            case INTERFACE_OR_ANNOTATION:
                includeImplementedInterfaces = includeAnnotations = true;
                break;
            default:
                throw new IllegalArgumentException("Unknown ClassType: " + classType);
            }
        }
        if (includeStandardClasses && includeImplementedInterfaces && includeAnnotations) {
            includeAllTypes = true;
        }
        final Set<ClassInfo> classInfoSetFiltered = new LinkedHashSet<>(classes.size());
        for (final ClassInfo classInfo : classes) {
            // Check class type against requested type(s)
            if ((includeAllTypes //
                    || includeStandardClasses && classInfo.isStandardClass()
                    || includeImplementedInterfaces && classInfo.isImplementedInterface()
                    || includeAnnotations && classInfo.isAnnotation()) //
                    // Always check blacklist 
                    && !scanSpec.classOrPackageIsBlacklisted(classInfo.name) //
                    // Always return whitelisted classes, or external classes if enableExternalClasses is true
                    && (!classInfo.isExternalClass || scanSpec.enableExternalClasses
                    // Return external (non-whitelisted) classes if viewing class hierarchy "upwards" 
                            || !strictWhitelist)) {
                // Class passed strict whitelist criteria
                classInfoSetFiltered.add(classInfo);
            }
        }
        return classInfoSetFiltered;
    }

